package ua.ember;
import android.app.*;
import android.content.*;
import android.content.pm.ServiceInfo;
import android.media.projection.*;
import android.os.*;
import org.json.*;

public final class EmberService extends Service {
 public interface Listener {void state(JSONObject data);}
 public final class LocalBinder extends Binder {public EmberService service(){return EmberService.this;}}
 private final Handler handler=new Handler(Looper.getMainLooper());private final LocalBinder binder=new LocalBinder();
 private BleController ble;private PlaybackAudio audio=new PlaybackAudio();private MediaProjection projection;private final EffectEngine engine=new EffectEngine();private final ReactiveEngine reactive=new ReactiveEngine();
 private EffectEngine.Signal signal;private Listener listener;private boolean pendingBeat,audioReady,foreground;private String message="Вибери свою стрічку.",reactiveId="",pendingPlay="";private int color=0xff5a1f,profile=2,brightness=70,speed=50,lastMode=138,micMode=-1,micSensitivity=35,lastColor=0xff5a1f;private boolean lastIsColor;private int packets;private long latency,lastEmit;private boolean releasing;
 public void onCreate(){super.onCreate();SharedPreferences p=getSharedPreferences("ember",0);profile=p.getInt("profile",2);brightness=p.getInt("brightness",70);speed=p.getInt("speed",50);lastMode=p.getInt("lastMode",138);lastColor=p.getInt("lastColor",color);lastIsColor=p.getBoolean("lastIsColor",false);micMode=p.getInt("micMode",-1);micSensitivity=p.getInt("micSensitivity",35);color=lastColor;ble=new BleController(this,handler,new BleController.Listener(){public void changed(boolean ok,String text){message=text;if(ok){profile=ble.profile();if(profile==3)micMode=-1;lastMode=Math.max(profile==1?0:135,Math.min(profile==1?212:profile==3?149:156,lastMode));save();SavedDevices.remember(EmberService.this,ble.address(),ble.name(),profile);}if(!ok){engine.stop();reactiveId="";stopAudio();}lastEmit=0;emit();}public void written(long ms,int sent){latency=ms;packets=sent;}});NotificationManager n=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);n.createNotificationChannel(new NotificationChannel("ember","Керування стрічкою",NotificationManager.IMPORTANCE_LOW));handler.post(tick);}
 public IBinder onBind(Intent i){return binder;}
 public int onStartCommand(Intent i,int flags,int id){return START_NOT_STICKY;}
 public void attach(Listener l){listener=l;lastEmit=0;emit();}
 private void notifyForeground(boolean capture){Notification note=new Notification.Builder(this,"ember").setSmallIcon(R.drawable.logo).setContentTitle("Ember").setContentText(capture?"Синхронізація зі звуком телефона":"Керування стрічкою").setOngoing(true).setContentIntent(PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE)).build();if(Build.VERSION.SDK_INT>=29)startForeground(40,note,ServiceInfo.FOREGROUND_SERVICE_TYPE_CONNECTED_DEVICE|(capture?ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PROJECTION:0));else startForeground(40,note);foreground=true;}
 private double now(){return SystemClock.elapsedRealtime()/1000.0;}
 private final Runnable tick=new Runnable(){public void run(){try{EffectEngine.Signal fresh=signal!=null&&SystemClock.elapsedRealtime()-signal.timeMs<=400?signal:null;boolean beat=pendingBeat;pendingBeat=false;if(!releasing&&ble.connected()&&!engine.paused){if(!reactiveId.isEmpty())ble.writeLatest(LedProtocol.color(reactive.render(reactiveId,color,now(),fresh,beat)));else if(engine.running)ble.writeLatest(LedProtocol.color(engine.sample(now(),beat,fresh)));}emit();}catch(Exception e){message=e.getMessage();engine.stop();reactiveId="";}handler.postDelayed(this,20);}};
 private void save(){getSharedPreferences("ember",0).edit().putInt("profile",profile).putInt("brightness",brightness).putInt("speed",speed).putInt("lastMode",lastMode).putInt("lastColor",lastColor).putBoolean("lastIsColor",lastIsColor).putInt("micMode",micMode).putInt("micSensitivity",micSensitivity).apply();}
 private void send(byte[] data){ble.write(data);}
 private void leaveMic(){send(LedProtocol.mic(false));}
 private void idle(){engine.stop();reactiveId="";stopAudio();}
 private void fallback(){send(LedProtocol.brightness(brightness,profile));if(micMode>=0){send(LedProtocol.mic(true));send(LedProtocol.micMode(MicPresets.MODES[Math.max(0,Math.min(15,micMode))]));send(LedProtocol.sensitivity(micSensitivity));}else{leaveMic();send(lastIsColor?LedProtocol.color(lastColor):LedProtocol.mode(lastMode,profile));send(LedProtocol.speed(speed,profile));}}
 public void command(String kind,String value){try{switch(kind){case "connect":releasing=false;notifyForeground(false);JSONObject target=new JSONObject(value);ble.connect(target.getString("address"),target.optString("name"));break;case "color":idle();color=Integer.parseInt(value.replace("#",""),16);leaveMic();send(LedProtocol.brightness(brightness,profile));send(LedProtocol.color(color));lastColor=color;lastIsColor=true;micMode=-1;save();break;case "brightness":brightness=Integer.parseInt(value);send(LedProtocol.brightness(brightness,profile));save();break;case "speed":speed=Integer.parseInt(value);send(LedProtocol.speed(speed,profile));save();break;case "mode":idle();leaveMic();lastMode=Integer.parseInt(value);if(profile==1&&lastMode>=135&&lastMode<=138)lastMode=new int[]{77,78,79,80}[lastMode-135];if(profile==1&&lastMode==149)lastMode=181;send(LedProtocol.mode(lastMode,profile));send(LedProtocol.brightness(brightness,profile));send(LedProtocol.speed(speed,profile));lastIsColor=false;micMode=-1;save();break;case "mic":if(!DeviceProfiles.hasMicrophone(profile))throw new IllegalStateException("Звуковий сенсор цієї стрічки не підтримується.");idle();micMode=Integer.parseInt(value);MicPresets.check(micMode);send(LedProtocol.brightness(brightness,profile));send(LedProtocol.mic(true));send(LedProtocol.micMode(MicPresets.MODES[micMode]));micSensitivity=MicPresets.SENSITIVITY[micMode];send(LedProtocol.sensitivity(micSensitivity));save();break;case "sensitivity":micSensitivity=Integer.parseInt(value);send(LedProtocol.sensitivity(micSensitivity));save();break;case "power":send(LedProtocol.power("on".equals(value),profile));break;case "reactive":if(!audioReady)throw new IllegalStateException("Спершу дозволь звук телефона.");engine.stop();leaveMic();send(LedProtocol.brightness(brightness,profile));reactive.reset();reactiveId=value;break;case "play":play(value);break;case "pause":if(engine.paused)engine.resume(now());else engine.pause(now());break;case "next":engine.next();break;case "stop":idle();if(ble.connected())fallback();break;case "release":releasing=true;idle();if(ble.connected()){fallback();ble.whenDrained(()->{ble.close();message="Стрічку звільнено.";lastEmit=0;emit();stopForeground(STOP_FOREGROUND_REMOVE);foreground=false;stopSelf();});}else{ble.close();stopForeground(STOP_FOREGROUND_REMOVE);foreground=false;stopSelf();}break;default:throw new IllegalArgumentException("Невідома команда.");}}catch(Exception e){message=e.getMessage();}lastEmit=0;emit();}
 private void play(String raw)throws Exception {if(!ble.connected())throw new IllegalStateException("Підключи стрічку.");JSONObject effect=new JSONObject(raw);JSONArray list=effect.getJSONArray("steps");EffectEngine.Step[] steps=new EffectEngine.Step[list.length()];for(int i=0;i<steps.length;i++){JSONObject s=list.getJSONObject(i);EffectEngine.Step st=new EffectEngine.Step();st.color=Integer.parseInt(s.getString("color").substring(1),16);st.durationMs=s.getInt("durationMs");st.trigger=s.getString("trigger");st.transition=s.getString("transition");JSONObject c=s.optJSONObject("condition");if(c!=null){st.thresholdDb=c.getDouble("thresholdDb");st.beatCount=c.getInt("beatCount");st.holdMs=c.getInt("holdMs");st.timeoutMs=c.getInt("timeoutMs");}st.validate();steps[i]=st;}boolean needs=false;for(EffectEngine.Step s:steps)needs|=s.trigger.startsWith("music");if(needs&&!audioReady)throw new IllegalStateException("Цей ефект потребує дозволу на звук телефона.");leaveMic();send(LedProtocol.brightness(brightness,profile));reactiveId="";engine.start(steps,effect.getBoolean("repeat"),now());message="Відтворення: "+effect.getString("name");}
 public void startAudio(int resultCode,Intent data){try{if(!ble.connected())throw new IllegalStateException("Спершу підключи стрічку.");stopAudio();notifyForeground(true);MediaProjectionManager m=(MediaProjectionManager)getSystemService(MEDIA_PROJECTION_SERVICE);projection=m.getMediaProjection(resultCode,data);final MediaProjection session=projection;session.registerCallback(new MediaProjection.Callback(){public void onStop(){handler.post(()->{if(projection!=session)return;stopAudio();engine.stop();reactiveId="";message="Дозвіл на захоплення звуку завершено.";emit();});}},handler);audio.start(projection,new PlaybackAudio.Listener(){public void frame(EffectEngine.Signal frame){handler.post(()->{if(projection==session&&audioReady){signal=frame;pendingBeat|=frame.beat;if(!releasing&&ble.connected()&&!engine.paused&&!reactiveId.isEmpty()){boolean hit=pendingBeat;pendingBeat=false;try{ble.writeLatest(LedProtocol.color(reactive.render(reactiveId,color,now(),signal,hit)));}catch(Exception e){message=e.getMessage();reactiveId="";}}}});}public void error(String text){handler.post(()->{if(projection!=session)return;message=text;engine.stop();reactiveId="";stopAudio();});}});audioReady=true;message="Звук телефона активний. Вибери музичний ефект.";}catch(Exception e){stopAudio();message=e.getMessage();}emit();}
 private void stopAudio(){audioReady=false;signal=null;pendingBeat=false;audio.stop();MediaProjection old=projection;projection=null;if(old!=null)old.stop();}
 private void emit(){if(listener==null)return;long stamp=SystemClock.elapsedRealtime();if(stamp-lastEmit<125)return;lastEmit=stamp;try{JSONObject o=new JSONObject().put("connected",ble.connected()).put("message",message).put("audioReady",audioReady).put("playing",engine.running||!reactiveId.isEmpty()).put("paused",engine.paused).put("step",engine.index+1).put("steps",engine.size()).put("trigger",engine.currentTrigger()).put("packets",packets).put("latency",latency).put("profile",profile).put("deviceName",ble.name()).put("hasMicrophone",DeviceProfiles.hasMicrophone(profile)).put("savedDevices",SavedDevices.load(this)).put("brightness",brightness).put("speed",speed).put("micSensitivity",micSensitivity);EffectEngine.Signal f=signal!=null&&SystemClock.elapsedRealtime()-signal.timeMs<=400?signal:null;o.put("rms",f==null?JSONObject.NULL:EffectEngine.db(f.rms)).put("bass",f==null?JSONObject.NULL:EffectEngine.db(f.bass)).put("bpm",f==null?JSONObject.NULL:f.bpm).put("beats",f==null?0:f.beats);JSONArray bars=new JSONArray();for(int i=0;i<32;i++)bars.put(f==null?0:f.spectrum[i]);o.put("spectrum",bars);listener.state(o);}catch(JSONException ignored){}}
 public void onDestroy(){handler.removeCallbacksAndMessages(null);idle();ble.close();listener=null;super.onDestroy();}
}
